entries[90997] = { ["name"] = "Nifflevar Bearded Axe", ["text"] = "2 sec cast 15\nMany of the axes forged by the vrykul display an unusual style: the bottom edge of the axe blade extends down below the width of the butt. This style increases cutting area while minimizing weight; it can be used on both weapon and tools. Some dwarven axes show a similar construction.\nNifflevar Bearded Axe\nBinds to Warband\nOne-Hand Axe\n3 - 8 Damage Speed 2.60\n(2.1 damage per second)\n+1 Agility\n+4 Stamina\n+ 2 Critical Strike\n+ 1 Haste\nDurability 110 / 110\n27" }
entries[90998] = { ["name"] = "Song of Sorrow", ["text"] = "Your spells that damage a target below 35% health grant 226 spell power for 10 sec. Cannot activate again for 10 sec after bonus expires.\n(20s cooldown)" }
entries[90999] = { ["name"] = "Throw", ["text"] = "35 yd range\n1.5 sec cast\nThrows your weapon, inflicting 200% weapon damage on the target." }
