entries[91012] = { ["name"] = "Flint Striker", ["text"] = "2 sec cast 5\nThis simple striker of flint and steel was used to start fires. The rod is carved like a dragon's head, while the flat blade of metal is fashioned to look like a stylized fish.\nFlint Striker\nBinds when picked up" }
entries[91013] = { ["name"] = "Timeroot", ["text"] = "Instant\nIncreases your spell power by 1926 for 15 sec." }
entries[91014] = { ["name"] = "Fanged Cloak Pin", ["text"] = "2 sec cast 5\nThis brooch would have been used to fasten a vrykul greatcloak around the shoulders. Attached to the cruciform main pin are two large but dulled teeth, most likely from an aging proto-drake. It's unclear whether the brooch's owner felt some affinity for the old drake or whether that creature was all he was capable of defeating.\nFanged Cloak Pin\nBinds when picked up" }
