entries[91084] = { ["name"] = "Thorned Necklace", ["text"] = "2 sec cast 5\nThis necklace looks like it might be painful to wear. It is formed of a wreath of bronze thorns, but unfortunately many of the spines point inward. It might have been worn by a runecaster or just designed by an artist with poor foresight.\nThorned Necklace\nBinds when picked up" }
