entries[91197] = { ["name"] = "Six-Clawed Cornice", ["text"] = "2 sec cast 5\nThis stone object was likely a decorative projection on a wall or tower from dark Azjol-Nerub. It appears to be a cross between an insect and spider and has been lacquered in green, purple and gold that fluoresce in low light.\nSix-Clawed Cornice\nBinds when picked up" }
