entries[91769] = { ["name"] = "Umbra Crescent", ["text"] = "2 sec cast 5\nThis is a circular blade favored by night elf Watchers. This type of weapon was most famously wielded by Maiev Shadowsong, but can be seen even today on night elves such as the Barrow Deeps Watchers on Mount Hyjal. It is likely the weapon you have recovered was magical before it was broken into so many fragments.\nUmbra Crescent\nBinds when picked up" }
entries[91770] = { ["name"] = "Signal Flare 01" }
entries[91771] = { ["name"] = "Wisp Form", ["text"] = "Instant\nTake on wisp form for 2 min." }
entries[91773] = { ["name"] = "Wisp Amulet", ["text"] = "2 sec cast 15\nWisps are nature spirits thought to be dead night elves. They exist in tight connection with their forest homeland and night elves in general, performing such beneficial activities as construction, repair and defense of elven communities. Many wisps sacrificed themselves in order to defeat Archimonde at the end of the Third War, so there are fewer wisps today than there once were.\nWisp Amulet\nBinds when picked up\nToy\nUse: Take on wisp form for 2 min. (10 Min Cooldown)" }
entries[91774] = { ["name"] = "Signal Flare 01 Kill Credit" }
entries[91775] = { ["name"] = "Castle of Sand", ["text"] = "2 sec cast 5\nThis is a small square fortress made of sand. The square towers and sun motif suggest tol'vir architecture, but you haven't seen this exact floor plan anywhere in Uldum. The object is clearly made of sand, not sandstone, so you're unsure what holds it together.\nCastle of Sand\nBinds when picked up" }
entries[91776] = { ["name"] = "Claw", ["text"] = "40 Energy Melee Range\nInstant\nClaw the enemy, dealing [0.54 * (Attack Power * 0.3) * (1 + Versatility) * 1 ] Physical damage." }
