entries[91792] = { ["name"] = "Sketch of a Desert Palace", ["text"] = "2 sec cast 5\nThese are architectural plans, though the architect apparently dreamed on a very big scale. You are unaware of any structure resembling this palace in modern Uldum, so it is likely the palace was never built. 'Commissioned for Emperor Ninjter.'\nSketch of a Desert Palace\nBinds when picked up" }
entries[91793] = { ["name"] = "Pipe of Franclorn Forgewright", ["text"] = "2 sec cast 5\nForgewright was a celebrated architect from the Dark Iron clan. He oversaw the construction of, among other things, the Stonewrought Dam and much of Blackrock Depths. It is said his ghost can still be seen within Blackrock Mountain.\nPipe of Franclorn Forgewright\nBinds when picked up" }
